def _approve_sheets(lesson: Lesson) -> None:
    for pass_ in ('ink', 'colour'):
        lesson.approve('niccolo', pass_, f'sheets/niccolo-{pass_}.png', 'bart', '2026-11-26')
    lesson.cast['characters']['niccolo']['palette'] = {'cloak': RED}


