def test_a_sheet_bart_has_not_approved_stops_the_request(lesson, tmp_path):
    with pytest.raises(Refused, match='does not exist yet'):
        packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'pack')


def test_a_sheet_that_changed_after_approval_needs_approval_again(lesson, tmp_path):
    _approve_sheets(lesson)
    _picture(lesson.media / 'sheets' / 'niccolo-ink.png', '#FAFAFA')
    with pytest.raises(Refused, match='changed after bart approved it'):
        packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'pack')


def test_the_pack_holds_every_attachment_with_its_hash_in_attach_order(lesson, tmp_path):
    _approve_sheets(lesson)
    out = packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'pack')
    manifest = json.loads((out / 'manifest.json').read_text())

    assert [a['role'] for a in manifest['attachments']] == ['blocking', 'identity', 'style']
    for item in manifest['attachments']:
        assert sha256(out / item['file']) == item['sha256']
        assert item['role'] == 'blocking' or item['sha256'] == sha256(Path(item['source'])), 'the approved file itself, byte for byte'
        assert packs.REFERENCE_MARK in item['file'], 'an ink request is a new picture: every input is a reference'
    prompt = (out / 'prompt.txt').read_text()
    assert 'Use the history-lines skill, pass 1 (ink) only.' in prompt
    assert 'Image 2 shows Niccolò' in prompt and '10 to 14%' in prompt
    assert 'Niccolò (image 2) is the rider in front' in prompt, 'each person is bound to a figure in each cell'
    assert 'walled village: small, far right. About 10% of the frame wide, centred 50% across.' in prompt, 'sizes come from the layout'
    assert (out / 'inputs.png').is_file()


def test_the_colour_pass_attaches_the_coloured_sheet_and_the_fixed_colours(lesson, tmp_path):
    _approve_sheets(lesson)
    ink = _board(tmp_path / 'ink.png', None)
    with pytest.raises(Refused, match='not the one recorded as approved'):
        packs.build(lesson, 'plain', 'plain-a', 'colour', tmp_path / 'early', ink)

    ledger.add(lesson.media, {'event': 'ink-approved', 'board': 'plain-a', 'sha256': sha256(ink)})
    palette = lesson.cast['characters']['niccolo'].pop('palette')
    with pytest.raises(Refused, match='no fixed colours sampled'):
        packs.build(lesson, 'plain', 'plain-a', 'colour', tmp_path / 'unsampled', ink)
    lesson.cast['characters']['niccolo']['palette'] = palette
    out = packs.build(lesson, 'plain', 'plain-a', 'colour', tmp_path / 'pack', ink)
    files = [a['file'] for a in json.loads((out / 'manifest.json').read_text())['attachments']]

    assert packs.REFERENCE_MARK not in files[0], 'the ink board is the picture being coloured, not a reference'
    assert [f.split('-')[2].split('.')[0] for f in files[1:]] == ['identity', 'colours', 'style']
    prompt = (out / 'prompt.txt').read_text()
    assert f'cloak {RED}' in prompt and "row 1 Niccolò's cloak" in prompt


def test_a_horse_with_no_signature_colour_does_not_block_the_colour_pass(lesson, tmp_path):
    _approve_sheets(lesson)
    lesson.cast['characters']['horse'] = {'name': 'Bay', 'kind': 'horse', 'look': 'A bay horse.'}
    for pass_ in ('ink', 'colour'):
        _picture(lesson.media / 'sheets' / f'horse-{pass_}.png', 'white' if pass_ == 'ink' else '#8B5A2B')
        lesson.approve('horse', pass_, f'sheets/horse-{pass_}.png', 'bart', '2026-11-26')
    scene = lesson.scene('plain')
    for cell in scene['boards'][0]['cells']:
        cell['who'] = ['niccolo', 'horse']
    write(lesson.dir / 'scenes' / 'plain.json', scene)
    ink = _board(tmp_path / 'ink.png', None)
    ledger.add(lesson.media, {'event': 'ink-approved', 'board': 'plain-a', 'sha256': sha256(ink)})
    out = packs.build(lesson, 'plain', 'plain-a', 'colour', tmp_path / 'pack', ink)
    assert 'Bay' in (out / 'prompt.txt').read_text()


def test_nothing_is_sent_before_bart_saw_the_inputs_and_a_changed_pack_is_refused(lesson, tmp_path):
    _approve_sheets(lesson)
    out = packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'pack')
    with pytest.raises(Refused, match='has not seen the exact inputs'):
        packs.sent(out, 'chatgpt', 'x', '2026-11-26', lesson.media)

    packs.seen(out, '2026-11-26')
    packs.sent(out, 'chatgpt', 'x', '2026-11-26', lesson.media)
    assert ledger.tally(lesson.media)['requests'] == 1

    (out / 'prompt.txt').write_text('something else')
    with pytest.raises(Refused, match='prompt.txt changed'):
        packs.seen(out, '2026-11-26')


