def test_the_same_failure_twice_stops_the_retries_until_the_approach_changes(lesson, tmp_path):
    _approve_sheets(lesson)
    for _ in range(2):
        ledger.add(lesson.media, {'event': 'rejected', 'board': 'plain-a', 'failures': ['colour-drift:niccolo']})
    with pytest.raises(Refused, match='already failed 2 times'):
        packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'again')
    packs.build(lesson, 'plain', 'plain-a', 'ink', tmp_path / 'again', changed='sheet attached in pass 2')
    assert ledger.repeated(lesson.media, 'plain-a') == {}


