def test_only_the_board_bart_approved_is_cut_and_the_crops_are_recorded(lesson, tmp_path, monkeypatch):
    _approve_sheets(lesson)
    write(lesson.cast_file, lesson.cast)
    monkeypatch.setattr(shots, 'Lesson', lambda slug: Lesson(slug, tmp_path / 'shots', tmp_path / 'media', tmp_path / 'style'))
    ink, col = _board(tmp_path / 'ink.png', None), _board(tmp_path / 'col.png', RED)
    marks = tmp_path / 'marks.json'
    write(marks, {'marks': dict(verify.SCORE), 'instant_no': []})

    assert shots.main(['cut', 'test', 'plain', 'plain-a', str(col)]) == 2
    assert shots.main(['accept', 'test', 'plain', 'plain-a', 'ink', str(ink), '--by', 'claude']) == 2, 'two reviewers'
    assert shots.main(['accept', 'test', 'plain', 'plain-a', 'ink', str(ink), '--by', 'claude,chatgpt']) == 0
    assert shots.main(['accept', 'test', 'plain', 'plain-a', 'colour', str(col), '--ink', str(ink), '--by', 'claude,chatgpt', '--marks', str(marks)]) == 2
    assert shots.main(['accept', 'test', 'plain', 'plain-a', 'colour', str(col), '--ink', str(ink), '--by', 'claude,chatgpt,bart', '--marks', str(marks)]) == 0
    assert shots.main(['cut', 'test', 'plain', 'plain-a', str(col)]) == 0

    folder = lesson.media / 'stills' / 'plain-a'
    crops = json.loads((folder / 'crops.json').read_text())
    assert [c['shot'] for c in crops['crops']] == [1, 2, 3, 4] and crops['upscale'] == 'lanczos'
    assert Image.open(folder / 'plain-a-shot-01.png').size == (1920, 1080)
    assert ledger.tally(lesson.media)['cells_accepted'] == 4


