# ── the ink gate on sheets ──────────────────────────────────────────────────────────────────────

def _lines(path: Path, wash: bool = False, horse: tuple[int, int] = (300, 160)) -> Path:
    """An ink drawing made at four times the size and scaled down, so its lines have soft grey edges like a real one."""
    big = Image.new('RGB', (1600, 900), 'white')
    draw = ImageDraw.Draw(big)
    w, h = horse
    for i in range(3):
        left = 120 + i * 500
        draw.rectangle([left, 300, left + w, 300 + h], outline='black', width=14)           # body
        for x in (left + 20, left + w - 40):
            draw.line([x, 300 + h, x, 700], fill='black', width=14)                         # legs
        for k in range(14):
            draw.line([left + 20 + k * 20, 330, left + 20 + k * 20, 280 + h], fill='black', width=8)   # hatching
        if wash:
            draw.rectangle([left + 30, 320, left + w - 30, 280 + h], fill=(150, 150, 150))
    small = big.resize((400, 225), Image.LANCZOS)
    small.save(path)
    return path


def test_soft_line_edges_are_not_grey_shading_but_a_wash_is(tmp_path):
    assert colour.grey_shading(colour.load(_lines(tmp_path / 'clean.png'))) <= verify.GREY_MAX
    washed = verify.sheet(_lines(tmp_path / 'wash.png', wash=True))
    assert 'grey-shading' in washed['failures']


def test_a_sheet_with_colour_in_it_is_not_an_ink_sheet(tmp_path):
    path = _lines(tmp_path / 'red.png')
    image = Image.open(path)
    ImageDraw.Draw(image).rectangle([10, 10, 80, 60], fill=(200, 40, 40))
    image.save(path)
    assert 'ink-has-colour' in verify.sheet(path)['failures']


def test_a_sheet_too_light_or_too_dark_fails_the_ink_gate(tmp_path):
    blank = tmp_path / 'blank.png'
    Image.new('RGB', (400, 225), 'white').save(blank)
    assert verify.sheet(blank)['failures'] == ['ink-weight']
    dark = tmp_path / 'dark.png'
    Image.new('RGB', (400, 225), 'black').save(dark)
    assert {'ink-weight', 'paper'} <= set(verify.sheet(dark)['failures'])


def _ink_board(path: Path, shares: list[float]) -> Path:
    """A 2x2 board whose cells carry the given share of black ink (a block in the corner of each cell)."""
    image = Image.new('RGB', (800, 450), 'white')
    draw = ImageDraw.Draw(image)
    for share, (left, top, right, bottom) in zip(shares, boards.cells(800, 450, 2, 2)):
        side = round(((right - left) * (bottom - top) * share / 100) ** 0.5)
        draw.rectangle([left + 20, top + 20, left + 20 + side - 1, top + 20 + side - 1], fill='black')
    image.save(path)
    return path


def test_an_empty_wide_cell_does_not_fail_a_board_whose_average_ink_is_right(tmp_path):
    board = {'kind': 'bright', 'grid': [2, 2], 'cells': [{}] * 4}
    light = verify.ink(board, _ink_board(tmp_path / 'light.png', [1, 7, 7, 7]))
    assert 'ink-weight' not in light['failures']
    dark = verify.ink(board, _ink_board(tmp_path / 'dark.png', [1, 7, 7, 14]))
    assert 'ink-weight' in dark['failures']


def test_a_white_garment_samples_as_white_not_as_its_grey_folds():
    box = np.full((40, 40, 3), 244.0)
    box[::6] = 200.0                                    # a few grey shadow folds
    assert colour.is_paper(colour.sample(box))
    assert not colour.is_paper(colour.sample(np.full((40, 40, 3), [216.0, 66.0, 56.0])))


