def test_unsky_takes_the_sky_wash_back_to_paper_and_leaves_a_blue_cloak_alone():
    rgb = np.full((200, 300, 3), 250.0)
    rgb[:80] = (205, 222, 242)                     # pale sky wash at the top
    rgb[80:83] = 20                                # horizon line in ink
    rgb[120:180, 100:160] = (107, 140, 183)        # Maffeo's blue cloak, lower down
    rgb[130:140, 20:60] = (205, 222, 242)          # pale blue not touching the sky
    out, changed = colour.unsky(rgb)
    assert colour.is_paper(colour.rgb_hex(out[10, 10]))
    assert (out[150, 130] == rgb[150, 130]).all()
    assert (out[135, 40] == rgb[135, 40]).all()
    assert (out[81, 50] == rgb[81, 50]).all()
    assert 35 < changed < 45


def test_the_colour_prompt_keeps_the_sky_bare_paper():
    import inspect
    assert 'no blue wash in the sky' in inspect.getsource(packs)


def test_unsky_on_a_board_whose_whole_background_is_washed_paints_true_paper():
    rgb = np.full((200, 300, 3), 0.0)
    rgb[:] = (231, 241, 249)                       # the faintest wash everywhere, nothing left as paper
    rgb[100:103] = 20
    out, _ = colour.unsky(rgb)
    assert colour.rgb_hex(out[10, 10]) == colour.PAPER_WHITE


def _horse(path=None):
    """A drawn 'horse': an ink-outlined body in chestnut, a darker mane shape, a white sock closed by ink."""
    rgb = np.full((200, 300, 3), 252.0)
    rgb[60:140, 60:240] = (200, 110, 60)             # coat
    rgb[40:60, 60:120] = (140, 80, 50)               # mane, darker than the coat
    rgb[140:180, 80:100] = 252                       # white sock, paper inside the figure
    for y0, y1, x0, x1 in [(38, 40, 58, 122), (38, 142, 58, 60), (38, 60, 120, 122), (58, 60, 120, 242),
                           (58, 142, 240, 242), (140, 142, 100, 242), (140, 142, 58, 80),
                           (140, 182, 78, 80), (140, 182, 100, 102), (180, 182, 78, 102)]:
        rgb[y0:y1, x0:x1] = 15
    return rgb


def test_regions_split_a_horse_into_coat_mane_and_sock_and_recolour_changes_only_the_coat(tmp_path):
    import regions
    rgb = _horse()
    palette = {'coat': '#C86E3C', 'mane': '#8C5032', 'markings': '#FCF9F8'}
    label, names = regions.mark(rgb, palette)
    at = lambda y, x: names[label[y, x]]
    assert (at(100, 150), at(50, 90), at(160, 90), at(10, 10), at(39, 90)) == ('coat', 'mane', 'markings', 'background', 'line')
    src = tmp_path / 'colour.png'
    Image.fromarray(rgb.astype('uint8')).save(src)
    legend = regions.save(label, names, rgb, src, str(tmp_path / 'colour.regions'))
    masks = regions.read_map(tmp_path / 'colour.regions.png', legend)
    black = regions.recolour(rgb, masks, {'coat': '#1E1A1A'})
    assert colour.delta(black[100, 150], colour.hex_rgb('#1E1A1A')) < 3
    assert (black[50, 90] == rgb[50, 90]).all() and (black[160, 90] == rgb[160, 90]).all()
    assert (black[39, 90] == rgb[39, 90]).all()


def test_a_paler_wash_of_the_cloak_passes_but_a_rust_or_blue_cloak_still_drifts():
    lab = lambda h: colour.lab(colour.hex_rgb(h))
    red = lab('#D84238')
    assert colour.wash_delta(lab('#D76049'), red) <= colour.SAME      # caravanserai cell 1, measured 27 Nov
    assert colour.wash_delta(lab('#E1634D'), red) <= colour.SAME
    assert colour.wash_delta(lab('#A45446'), red) > colour.SAME       # rust
    assert colour.wash_delta(lab('#876247'), red) > colour.SAME       # brown
    assert colour.wash_delta(lab('#6B8CB7'), red) > colour.SAME       # Maffeo's blue


def test_fix_area_recolours_only_the_wrong_horse_inside_the_box():
    import regions
    rgb = np.full((100, 200, 3), 252.0)
    rgb[40:60, 20:40] = (122, 82, 54)      # tiny horse painted brown, should be black
    rgb[40:60, 120:140] = (122, 82, 54)    # another brown horse outside the box: Marco's chestnut, stays
    mask = regions.area(rgb, (10, 30, 50, 70), '#7A5236')
    out = regions.recolour(rgb, {'area': mask}, {'area': '#2A2422'})
    assert colour.delta(out[50, 30], colour.hex_rgb('#2A2422')) < 3
    assert (out[50, 130] == rgb[50, 130]).all() and (out[5, 5] == rgb[5, 5]).all()


def test_ink_kept_survives_an_edit_that_comes_back_a_pixel_off():
    import numpy as np
    import colour
    ink = np.full((941, 1671, 3), 252.0)
    ink[300:320, 200:1400] = 0
    off = np.full((942, 1670, 3), 252.0)
    off[300:320, 200:1400] = 0
    assert colour.ink_kept(ink, off) > 0.9
    tall = np.full((1200, 1670, 3), 252.0)
    assert colour.ink_kept(ink, tall) == 0.0


def test_thin_light_pen_strokes_are_not_grey_shading():
    rgb = np.full((200, 300, 3), 252.0)
    for y in range(20, 180, 8):
        rgb[y:y + 2, 20:280] = 150             # light ripple strokes, 2 px, far from any black ink
    assert colour.grey_shading(rgb) == 0
    rgb[60:120, 60:160] = 150                  # a grey wash patch still counts
    assert colour.grey_shading(rgb) > 5


def test_upscale_check_passes_a_faithful_upscale_and_catches_a_recolour():
    import numpy as np
    from PIL import Image
    import colour
    src = np.full((462, 828, 3), 250.0)
    src[100:110, 50:700] = 20
    src[200:400, 100:300] = (200, 80, 70)
    hd = np.asarray(Image.fromarray(src.astype(np.uint8)).resize((1920, 1080), Image.LANCZOS), dtype=np.float64)
    assert colour.upscale_check(src, hd)['failures'] == []
    bad = hd.copy()
    bad[430:930, 230:700] = (70, 90, 200)
    assert 'colour-drift' in colour.upscale_check(src, bad)['failures']
